AI_PROVIDER_SELECTOR_ENABLED = False
DEFAULT_AI_PROVIDER = AI_PROVIDER_OPENAI


def get_selected_ai_provider():
    """Return the active AI provider, forcing the configured default when selection is hidden."""
    if AI_PROVIDER_SELECTOR_ENABLED:
        return st.session_state.get("global_ai_provider", DEFAULT_AI_PROVIDER)
    return DEFAULT_AI_PROVIDER


def using_openai_provider():
    return get_selected_ai_provider() == AI_PROVIDER_OPENAI


def active_ai_provider_name():
    return "OpenAI GPT-6 Luna" if using_openai_provider() else "Gemini"


def render_ai_api_configuration(scope_key):
    """
    Render the API-key status/input for the currently selected provider.

    Existing Gemini deployments keep using st.secrets["API_KEY"]. OpenAI uses the
    separate st.secrets["OPENAI_API_KEY"] value so the two providers can coexist.
    """
    if using_openai_provider():
        if "OPENAI_API_KEY" in st.secrets:
            api_key = st.secrets["OPENAI_API_KEY"]
            st.success("✅ OpenAI API Key loaded from Secrets")
        else:
            api_key = st.text_input(
                "OpenAI API Key",
                type="password",
                key=f"{scope_key}_openai_api_key",
            )
            st.info("Paste your OpenAI API key here to run GPT-6 Luna.")
        st.caption("Model: GPT-6 Luna | Reasoning: medium | Strict Structured Outputs")
        return api_key

    if "API_KEY" in st.secrets:
        api_key = st.secrets["API_KEY"]
        st.success("✅ Gemini API Key loaded from Secrets")
    else:
        api_key = st.text_input(
            "Gemini API Key",
            type="password",
            key=f"{scope_key}_gemini_api_key",
        )
        st.info("Paste your Gemini API key here to run the tool.")
    st.caption("Primary model: Gemini 2.5 Flash | v23 source-fidelity safeguards enabled")
    return api_key


def _ai_balanced_json_object(text_value, start_index):
    """Return one balanced JSON-object substring beginning at start_index."""
    depth = 0
    in_string = False
    escape = False

    for idx in range(start_index, len(text_value)):
        ch = text_value[idx]

        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return text_value[start_index:idx + 1]

    return ""


def _ai_json_template_candidates(prompt):
    """Yield valid JSON objects embedded in a formatter prompt."""
    candidates = []
    for match in re.finditer(r"\{", str(prompt or "")):
        raw = _ai_balanced_json_object(str(prompt or ""), match.start())
        if not raw:
            continue
        try:
            parsed = json.loads(raw)
        except Exception:
            continue
        if isinstance(parsed, dict):
            candidates.append((match.start(), raw, parsed))
    return candidates


def _ai_template_score(value):
    """Prefer output skeletons (mostly blank/example values) over populated input JSON."""
    if isinstance(value, dict):
        if not value:
            return 0
        return 2 + sum(_ai_template_score(v) for v in value.values())
    if isinstance(value, list):
        if not value:
            return 2
        return 1 + sum(_ai_template_score(v) for v in value[:3])
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return 5
        # Output examples often use short instructional placeholders.
        if len(stripped) <= 80 and not re.search(r"\d{3,}", stripped):
            return 2
        return -1
    if value is None:
        return 3
    return 0


def _ai_find_output_template(prompt):
    """
    Locate the JSON output example already present in each existing formatter prompt.

    This lets OpenAI use strict Structured Outputs without maintaining a second,
    divergent schema beside every client-specific prompt.
    """
    prompt_text = str(prompt or "")
    candidates = _ai_json_template_candidates(prompt_text)
    if not candidates:
        raise RuntimeError(
            "OpenAI Structured Outputs could not locate a JSON output template in this prompt."
        )

    marker_patterns = [
        r"OUTPUT SCHEMA\s*:",
        r"OUTPUT FORMAT(?:\s*\(STRICT\))?",
        r"={5,}\s*OUTPUT\s*={5,}",
        r"\bOUTPUT\s*:",
        r"JSON Structure\s*:",
        r"Return ONLY valid JSON\s*:",
        r"Return valid JSON ONLY\s*\.?",
    ]

    marker_positions = []
    for pattern in marker_patterns:
        marker_positions.extend(
            m.end() for m in re.finditer(pattern, prompt_text, flags=re.IGNORECASE)
        )

    # First valid object after the latest explicit output marker is normally the
    # schema example. Use a bounded preference so later embedded resume JSON does
    # not outrank the explicit output section.
    for marker_pos in sorted(marker_positions, reverse=True):
        after = [c for c in candidates if c[0] >= marker_pos]
        if after:
            first = min(after, key=lambda c: c[0])
            if first[0] - marker_pos <= 5000:
                return first[2]

    # Fallback: choose the object that most resembles a blank/example template.
    return max(candidates, key=lambda c: (_ai_template_score(c[2]), -c[0]))[2]


def _ai_schema_from_template(value, path=()):
    """Convert an existing JSON output example to a strict JSON Schema."""
    if isinstance(value, dict):
        properties = {
            str(key): _ai_schema_from_template(val, path + (str(key),))
            for key, val in value.items()
        }
        return {
            "type": "object",
            "properties": properties,
            "required": list(properties.keys()),
            "additionalProperties": False,
        }

    if isinstance(value, list):
        if value:
            item_schema = _ai_schema_from_template(value[0], path + ("[]",))
        else:
            # Existing formatter prompts use empty arrays for lists of strings.
            item_schema = {"type": "string"}
        return {"type": "array", "items": item_schema}

    if isinstance(value, bool):
        return {"type": "boolean"}
    if isinstance(value, int) and not isinstance(value, bool):
        return {"type": "integer"}
    if isinstance(value, float):
        return {"type": "number"}
    if value is None:
        return {"type": ["string", "null"]}

    return {"type": "string"}


def _openai_generate_strict_json_text(api_key, prompt):
    """Call GPT-6 Luna through the Responses API with strict Structured Outputs."""
    try:
        from openai import OpenAI
    except Exception as exc:
        raise RuntimeError(
            "The OpenAI Python package is not available. Confirm 'openai' is in requirements.txt."
        ) from exc

    output_template = _ai_find_output_template(prompt)
    schema = _ai_schema_from_template(output_template)
    schema_fingerprint = hashlib.sha1(
        json.dumps(schema, sort_keys=True).encode("utf-8")
    ).hexdigest()[:12]

    client = OpenAI(api_key=api_key)
    response = client.responses.create(
        model=OPENAI_MODEL_ID,
        input=str(prompt),
        reasoning={"effort": OPENAI_REASONING_EFFORT},
        text={
            "format": {
                "type": "json_schema",
                "name": f"resume_formatter_{schema_fingerprint}",
                "schema": schema,
                "strict": True,
            }
        },
    )

    output_text = str(getattr(response, "output_text", "") or "").strip()
    if not output_text:
        raise RuntimeError("OpenAI returned no structured output text.")

    # Structured Outputs should already be valid JSON; parse once here so an
    # incomplete/refused response fails visibly instead of reaching Word output.
    parsed = json.loads(output_text)
    if not isinstance(parsed, dict):
        raise RuntimeError("OpenAI returned structured output that was not a JSON object.")

    return json.dumps(parsed, ensure_ascii=False)


class _AITextResponse:
    def __init__(self, text_value):
        self.text = text_value


class _OpenAIModelsAdapter:
    """Mimic the google-genai client.models.generate_content surface used by client call sites."""
    def __init__(self, api_key):
        self.api_key = api_key

    def generate_content(self, model=None, contents=None, config=None):
        # model/config are intentionally accepted for compatibility with the
        # unchanged Gemini call sites. GPT-6 Luna and strict JSON are controlled
        # centrally above when OpenAI is selected.
        return _AITextResponse(
            _openai_generate_strict_json_text(self.api_key, contents)
        )


class _OpenAIClientAdapter:
    def __init__(self, api_key):
        self.models = _OpenAIModelsAdapter(api_key)


def create_ai_client(api_key):
    """
    Return the original Gemini client or an OpenAI compatibility adapter.

    Both providers share the same v23 source-fidelity ingestion, client-specific
    prompts, validators, and downstream formatter logic. OpenAI uses GPT-6 Luna
    through Responses API Structured Outputs.
    """
    if using_openai_provider():
        return _OpenAIClientAdapter(api_key)
    return genai.Client(api_key=api_key)


def replace_tag_safely(p, tag, value, unbold=False, force_bold=False, font_name=None):
    if tag.lower() not in p.text.lower():
        return False
    replaced = False
    for run in p.runs:
        if tag.lower() in run.text.lower():
            pattern = re.compile(re.escape(tag), re.IGNORECASE)
            run.text = pattern.sub(str(value), run.text)
            if unbold:
                run.font.bold = False
            if force_bold:
                run.font.bold = True
            if font_name:
                run.font.name = font_name
            replaced = True
    if not replaced:
        full_text = p.text
        pattern = re.compile(re.escape(tag), re.IGNORECASE)
        new_text = pattern.sub(str(value), full_text)
        if p.runs:
            p.runs[0].text = new_text
            if unbold:
                p.runs[0].font.bold = False
            if force_bold:
                p.runs[0].font.bold = True
            if font_name:
                p.runs[0].font.name = font_name
            for i in range(1, len(p.runs)):
                p.runs[i].text = ""
    return True

def insert_bullet_line_after(paragraph, text, font_name=None):
    new_p_xml = copy.deepcopy(paragraph._p)
    paragraph._p.addnext(new_p_xml)
    new_p = Paragraph(new_p_xml, paragraph._parent)
    for run in new_p.runs:
        run._element.getparent().remove(run._element)
    if paragraph.runs:
        new_run = new_p.add_run(text)
        ref_font = paragraph.runs[0].font
        new_run.font.bold = ref_font.bold
        new_run.font.italic = ref_font.italic
        if ref_font.color and ref_font.color.rgb:
            new_run.font.color.rgb = ref_font.color.rgb
        new_run.font.size = ref_font.size
        if font_name:
            new_run.font.name = font_name
        else:
            new_run.font.name = ref_font.name
    else:
        new_p.add_run(text)
    return new_p

def delete_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None

def collapse_extra_blank_paragraphs(doc):
    """
    Collapse consecutive empty BODY paragraphs to a single blank paragraph.

    This is intentionally conservative:
    - Only operates on top-level document-body paragraphs.
    - Does NOT touch paragraphs inside tables.
    - Does NOT remove page-break or section-break paragraphs.
    - Preserves one intentional blank paragraph between sections.
    """

    body = doc.element.body
    previous_was_blank = False

    for element in list(body):

        # A table or other non-paragraph element breaks the blank-paragraph run.
        if not element.tag.endswith("}p"):
            previous_was_blank = False
            continue

        # ------------------------------------------------------------
        # DO NOT TOUCH STRUCTURAL PARAGRAPHS
        # ------------------------------------------------------------

        # Preserve section breaks.
        if element.xpath(".//w:sectPr"):
            previous_was_blank = False
            continue

        # Preserve explicit page/column/line breaks.
        if element.xpath(".//w:br"):
            previous_was_blank = False
            continue

        # Preserve drawings/images/shapes.
        if (
            element.xpath(".//w:drawing")
            or element.xpath(".//w:pict")
            or element.xpath(".//w:object")
        ):
            previous_was_blank = False
            continue

        # ------------------------------------------------------------
        # DETERMINE WHETHER PARAGRAPH IS VISUALLY EMPTY
        # ------------------------------------------------------------

        text_nodes = element.xpath(".//w:t")
        text = "".join(
            node.text or ""
            for node in text_nodes
        ).strip()

        is_blank = not text

        # ------------------------------------------------------------
        # COLLAPSE ONLY CONSECUTIVE BLANKS
        # ------------------------------------------------------------

        if is_blank:
            if previous_was_blank:
                body.remove(element)
            else:
                previous_was_blank = True
        else:
            previous_was_blank = False

def ensure_experience_spacing(doc, mapping):
    """
    Ensure one visible blank paragraph between consecutive work-history entries.

    This specifically protects dynamically generated jobs beyond the original
    seven template slots, including abbreviated older roles that have
    Company/Title/Dates but no bullets. Existing spacing is preserved; a new
    blank paragraph is added only when one is missing.
    """
    paragraphs = list(doc.paragraphs)
    company_pattern = re.compile(
        r"\{\{company(\d+)\}\}",
        flags=re.IGNORECASE,
    )

    role_locations = []

    for idx, paragraph in enumerate(paragraphs):
        match = company_pattern.search(paragraph.text or "")
        if not match:
            continue

        role_num = int(match.group(1))
        company_value = str(
            mapping.get(f"Company{role_num}", "") or ""
        ).strip()

        if company_value:
            role_locations.append((role_num, idx))

    if len(role_locations) < 2:
        return

    # Bottom-up so inserting a paragraph does not invalidate earlier indexes.
    for _, idx in reversed(role_locations[1:]):
        paragraphs = list(doc.paragraphs)

        if idx <= 0 or idx >= len(paragraphs):
            continue

        current_p = paragraphs[idx]
        previous_p = paragraphs[idx - 1]

        # Do nothing when the template/output already has a separator.
        if not previous_p.text.strip():
            continue

        blank = current_p.insert_paragraph_before("")

        try:
            blank.style = doc.styles["Normal"]
        except Exception:
            pass

        blank.paragraph_format.space_before = Pt(0)
        blank.paragraph_format.space_after = Pt(0)


def expand_experience_placeholders(doc, mapping):
    """
    Dynamically extend a template's work-history placeholder block when the
    candidate has more roles than the template was originally built to hold.

    Existing templates can stay exactly as they are (for example, through
    {{Company7}} / {{Dates7}} / {{Title7}} / {{Bullets7}}). If mapping contains
    Company8, Company9, etc., this function clones the final existing experience
    block and renumbers the placeholders before the normal replacement logic runs.

    This is deliberately template-driven rather than capped at an arbitrary
    number such as 20.
    """

    # Determine how many experience entries the mapping actually contains.
    mapped_indices = []
    for key in mapping.keys():
        match = re.fullmatch(
            r"(?i)(?:company|dates|title|bullets|environment|responsible)(\d+)",
            str(key),
        )
        if match:
            mapped_indices.append(int(match.group(1)))

    if not mapped_indices:
        return

    required_max = max(mapped_indices)

    # Locate the highest-numbered complete experience block already present
    # in the template body. Current client templates use paragraph-based
    # Company/Dates -> Title -> Bullets blocks.
    paragraphs = list(doc.paragraphs)
    placeholder_pattern = re.compile(
        r"\{\{(company|dates|title|bullets|environment|responsible)(\d+)\}\}",
        flags=re.IGNORECASE,
    )

    locations = {}
    for idx, paragraph in enumerate(paragraphs):
        for kind, number in placeholder_pattern.findall(paragraph.text or ""):
            number = int(number)
            locations.setdefault(number, {}).setdefault(kind.lower(), []).append(idx)

    complete_indices = [
        number
        for number, parts in locations.items()
        if "company" in parts and "title" in parts and "bullets" in parts
    ]

    if not complete_indices:
        return

    template_max = max(complete_indices)

    if required_max <= template_max:
        return

    parts = locations[template_max]
    block_start = min(
        parts["company"] + parts.get("dates", []) + parts["title"] + parts["bullets"]
    )
    block_end = max(
        parts["company"] + parts.get("dates", []) + parts["title"] + parts["bullets"]
    )

    # Include any Environment placeholder that belongs inside the same final block.
    if parts.get("environment"):
        block_end = max(block_end, max(parts["environment"]))

    # Preserve the template's inter-role spacing. Peraton, for example,
    # uses one blank Normal paragraph between experience blocks, while
    # the Fannie-style templates do not.
    if (
        block_start > 0
        and not paragraphs[block_start - 1].text.strip()
    ):
        block_start -= 1

    source_block = paragraphs[block_start:block_end + 1]
    if not source_block:
        return

    insert_after = source_block[-1]._p

    # Clone the final template block once for each additional candidate role.
    for new_index in range(template_max + 1, required_max + 1):
        cloned_elements = []

        for source_paragraph in source_block:
            new_p = copy.deepcopy(source_paragraph._p)

            # Renumber every placeholder in the cloned block that belongs to
            # the original final template index.
            text_nodes = new_p.xpath(".//w:t")
            combined_text = "".join(
                node.text or ""
                for node in text_nodes
            )

            # Word frequently splits one placeholder across multiple runs
            # (for example "{{" + "company" + "7" + "}}").  Once we confirm
            # this cloned paragraph belongs to the final template role, safely
            # renumber the placeholder fragments across those runs.
            if re.search(
                rf"(?i)\{{\{{(?:company|dates|title|bullets|environment|responsible){template_max}\}}\}}",
                combined_text,
            ):
                for text_node in text_nodes:
                    if not text_node.text:
                        continue

                    text_node.text = re.sub(
                        rf"(?i)(company|dates|title|bullets|environment|responsible){template_max}",
                        lambda m: f"{m.group(1)}{new_index}",
                        text_node.text,
                    )

                    if text_node.text.strip() == str(template_max):
                        text_node.text = text_node.text.replace(
                            str(template_max),
                            str(new_index),
                        )

            insert_after.addnext(new_p)
            insert_after = new_p
            cloned_elements.append(new_p)


def _remove_trailing_document_section(doc, heading_text):
    """
    Remove a trailing Word section beginning at a visible heading, regardless of
    whether that heading lives in a paragraph, table, or text-bearing shape.

    Capital One's Supplier Technical Interview section is the final section of
    its template. Removing from the heading through the end also removes the
    decorative horizontal lines when no Q&A was supplied.
    """
    body = doc._element.body
    children = list(body)
    target = re.sub(r"\s+", " ", str(heading_text or "")).strip().casefold()
    start_index = None

    for idx, child in enumerate(children):
        if child.tag.rsplit('}', 1)[-1] == 'sectPr':
            continue
        pieces = [node.text or "" for node in child.xpath('.//w:t')]
        visible = re.sub(r"\s+", " ", "".join(pieces)).strip().casefold()
        if target and target in visible:
            start_index = idx
            break

    if start_index is None:
        return False

    for child in list(body)[start_index:]:
        if child.tag.rsplit('}', 1)[-1] == 'sectPr':
            continue
        try:
            body.remove(child)
        except Exception:
            pass
    return True



def _bnsf_clean_summary_style(value):
    """
    Normalize BNSF AI-generated summary text for a template that already owns
    the visible bullet formatting.

    Summary content is generated/tailored copy, not immutable resume history, so
    deterministic presentation cleanup is safe here. Historical work-history
    bullets continue to use the strict source-fidelity path unchanged.
    """
    value = _modern_summary_clean_text(value)

    # Avoid awkward recruiter-summary openings such as "Bring 14 years..." or
    # "Brings immediate...". The remaining text is still the model's factual
    # statement, just expressed as the direct bullet fragment the template expects.
    value = re.sub(
        r"^(?:bring|brings|offers|possesses)\s+",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    if value and value[0].isalpha():
        value = value[0].upper() + value[1:]
    return value



def _prepare_fannie_interview_section(doc, mapping):
    """
    Make Fannie's trailing Supplier Technical Interview Results section deterministic.

    - zero complete Q/A pairs -> remove the entire trailing section;
    - keep only complete pairs (both question and answer populated);
    - compact non-contiguous pairs into sequential Q1/A1, Q2/A2, ...; and
    - remove unused placeholder paragraphs so no empty numbered slots remain.
    """
    if "FormerFM" not in mapping:
        return

    completed = []
    for idx in range(1, 6):
        question = str(mapping.get(f"Q{idx}", "") or "").strip()
        answer = str(mapping.get(f"A{idx}", "") or "").strip()
        if question and answer:
            completed.append((question, answer))

    for idx in range(1, 6):
        if idx <= len(completed):
            mapping[f"Q{idx}"], mapping[f"A{idx}"] = completed[idx - 1]
        else:
            mapping[f"Q{idx}"] = ""
            mapping[f"A{idx}"] = ""

    if not completed:
        _remove_trailing_document_section(doc, "SUPPLIER TECHNICAL INTERVIEW RESULTS")
        return

    keep_count = len(completed)
    for paragraph in list(doc.paragraphs):
        matches = re.findall(r"\{\{([QA])(\d)\}\}", str(paragraph.text or ""), flags=re.I)
        if not matches:
            continue
        slot_numbers = [int(number) for _, number in matches]
        if slot_numbers and min(slot_numbers) > keep_count:
            try:
                delete_paragraph(paragraph)
            except Exception:
                pass


def _prepare_bnsf_interview_section(doc, mapping):
    """
    Make the BNSF Supplier Technical Interview Results section match the actual
    completed Q/A pairs.

    BNSF's Word template contains five Q/A slots plus four VML horizontal-line
    paragraphs between them. Generic empty-placeholder deletion removes blank
    Q/A text but cannot see/remove those VML line objects. This helper therefore:

    - keeps only COMPLETE pairs (both question and answer are nonblank),
    - compacts non-contiguous complete pairs into Q1/A1, Q2/A2, ...,
    - removes the entire trailing interview section when zero pairs are complete,
    - otherwise removes unused Q/A paragraphs, and
    - keeps exactly N-1 divider lines for N displayed pairs.

    The helper is BNSF-only and does not alter other client templates.
    """
    if "FormerBNSF" not in mapping:
        return

    completed = []
    for idx in range(1, 6):
        question = str(mapping.get(f"Q{idx}", "") or "").strip()
        answer = str(mapping.get(f"A{idx}", "") or "").strip()
        if question and answer:
            completed.append((question, answer))

    # Compact completed pairs so the template numbering remains sequential even
    # if a recruiter happens to populate Q1/A1 and Q3/A3 but leaves Q2/A2 blank.
    for idx in range(1, 6):
        if idx <= len(completed):
            mapping[f"Q{idx}"], mapping[f"A{idx}"] = completed[idx - 1]
        else:
            mapping[f"Q{idx}"] = ""
            mapping[f"A{idx}"] = ""

    if not completed:
        _remove_trailing_document_section(
            doc,
            "SUPPLIER TECHNICAL INTERVIEW RESULTS",
        )
        return

    keep_count = len(completed)

    # Capture the four decorative horizontal-line paragraphs before deleting any
    # Q/A paragraphs. In the BNSF template these are VML <w:pict> paragraphs.
    divider_paragraphs = [
        paragraph
        for paragraph in list(doc.paragraphs)
        if paragraph._p.xpath('.//w:pict')
    ]

    # Remove template Q/A slots beyond the number of complete pairs. The normal
    # replacement pass will fill the retained slots.
    for paragraph in list(doc.paragraphs):
        text_value = str(paragraph.text or "")
        matches = re.findall(r"\{\{([QA])(\d)\}\}", text_value, flags=re.I)
        if not matches:
            continue
        slot_numbers = [int(number) for _, number in matches]
        if slot_numbers and min(slot_numbers) > keep_count:
            try:
                delete_paragraph(paragraph)
            except Exception:
                pass

    # Five pairs use four separator lines. For N retained pairs we want N-1
    # separators, with no line trailing the last displayed answer.
    divider_keep = max(0, keep_count - 1)
    for paragraph in divider_paragraphs[divider_keep:]:
        try:
            delete_paragraph(paragraph)
        except Exception:
            pass

def process_word_doc(temp_path, mapping, out_path):
    doc = docx.Document(temp_path)
    expand_experience_placeholders(doc, mapping)
    _prepare_fannie_interview_section(doc, mapping)
    _prepare_bnsf_interview_section(doc, mapping)
    ensure_experience_spacing(doc, mapping)
    
    # Check if this is the Peraton tool
    is_peraton = "CERTIFICATION1" in mapping
    target_font = 'Calibri' if is_peraton else None
    env_font = 'Calibri' if is_peraton else 'Times New Roman'

    # --- TWEAK 1: Remove "Certifications" Table & Header (All Clients) ---
    has_certifications = True
    if is_peraton:
        if not mapping.get("CERTIFICATION1"):
            has_certifications = False
    else:
        if not mapping.get("Certifications") or not str(mapping.get("Certifications")).strip():
            has_certifications = False

    if not has_certifications:
        tables_to_delete = []
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    # Made case-insensitive to ensure it catches the tag even if typed differently in template
                    if "{{certifications}}" in cell.text.lower() or "{{certification1}}" in cell.text.lower():
                        if table not in tables_to_delete:
                            tables_to_delete.append(table)
        for table in tables_to_delete:
            table._element.getparent().remove(table._element)
            
        paras = list(doc.paragraphs)
        for i, p in enumerate(paras):
            # Made case-insensitive to ensure the header text is caught
            if p.text.strip().lower() == "certifications":
                delete_paragraph(p)
                # Prevent a double-space gap by deleting the empty line above it if it exists
                if i > 0 and not paras[i-1].text.strip():
                    try:
                        delete_paragraph(paras[i-1])
                    except:
                        pass

    # --- TWEAK 2: Remove Q&A Section for ALL clients if empty (Including Fannie Mae) ---
    has_qa = any(mapping.get(k) and str(mapping.get(k)).strip() for k in ["Q1", "A1", "Q2", "A2", "Q3", "A3", "Q4", "A4", "Q5", "A5"])

    if not has_qa:
        # Capital One places this section at the very end of the template. Its
        # heading/decorative rules may live in tables/shapes rather than normal
        # paragraphs, so remove the entire trailing section from the heading onward.
        trailing_qa_removed = False
        if "FormerCapitalOne" in mapping or "FormerBNSF" in mapping or "FormerFM" in mapping:
            trailing_qa_removed = _remove_trailing_document_section(
                doc,
                "SUPPLIER TECHNICAL INTERVIEW RESULTS",
            )

        paras = list(doc.paragraphs)
        for i, p in enumerate(paras):
            if "SUPPLIER TECHNICAL INTERVIEW RESULTS" in p.text.upper():
                delete_paragraph(p)
                # Prevent a double-space gap by deleting the empty line above it if it exists
                if i > 0 and not paras[i-1].text.strip():
                    try:
                        delete_paragraph(paras[i-1])
                    except:
                        pass
        
        tables_to_delete = []
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    # Made case-insensitive for safety
                    if "{{q1}}" in cell.text.lower():
                        if table not in tables_to_delete:
                            tables_to_delete.append(table)
        for table in tables_to_delete:
            table._element.getparent().remove(table._element)
                
    # --- PERATON TWEAK 2: Space before Relevant Professional Experience ---
    if is_peraton:
        for p in list(doc.paragraphs):
            if "Relevant Professional Experience" in p.text:
                p.insert_paragraph_before("")
                break # Only do it once
            
    has_any_education = bool(mapping.get("School1") or mapping.get("School2") or mapping.get("School3"))
    for table in doc.tables:
        rows_to_delete = []
        for row in table.rows:
            row_text = "".join(cell.text for cell in row.cells).strip()
            for i in range(1, 4):
                tag = f"{{{{School{i}}}}}"
                if tag.lower() in row_text.lower() and not mapping.get(f"School{i}"):
                    if has_any_education and row not in rows_to_delete:
                        rows_to_delete.append(row)
        for row in rows_to_delete:
            table._tbl.remove(row._tr)
            
    paras_to_remove = []
    # Updated kill_keys with 'Certification', 'School', and 'Responsible'
    kill_keys = ['Company', 'Title', 'Bullets', 'Dates', 'Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'A1', 'A2', 'A3', 'A4', 'A5', 'Summary', 'Skill', 'Years', 'Certification', 'School', 'Responsible', 'BillRate', 'WorkStatus']
    for p in list(doc.paragraphs):
        for key, value in mapping.items():
            tag = f"{{{{{key}}}}}"
            if tag.lower() in p.text.lower():
                if not value or not str(value).strip():
                    if any(k.lower() in key.lower() for k in kill_keys):
                        if p not in paras_to_remove:
                            paras_to_remove.append(p)
                    else:
                        replace_tag_safely(p, tag, "", font_name=target_font)
                else:
                    if "Bullets" in key:
                        for run in p.runs:
                            if '\n' in run.text:
                                run.text = run.text.replace('\n', '')
                        lines = str(value).split('\n')
                        replace_tag_safely(p, tag, lines[0], font_name=target_font)
                        curr_p = p
                        for line in lines[1:]:
                            curr_p = insert_bullet_line_after(curr_p, line, font_name=target_font)
                        num_match = re.search(r'\d+', key)
                        if num_match:
                            env_val = mapping.get(f"Environment{num_match.group()}")
                            if env_val and str(env_val).strip():
                                env_p = curr_p.insert_paragraph_before("")
                                curr_p._p.addnext(env_p._p)
                                try:
                                    env_p.style = doc.styles['Normal']
                                except:
                                    pass
                                env_p.paragraph_format.left_indent = Pt(0)
                                env_p.paragraph_format.space_after = Pt(0)
                                clean_env = re.sub(r'^Environment\s*:\s*', '', str(env_val).strip(), flags=re.IGNORECASE)
                                b_run = env_p.add_run("Environment: ")
                                b_run.bold = True
                                b_run.font.name = env_font
                                b_run.font.size = Pt(12)
                                n_run = env_p.add_run(clean_env)
                                n_run.bold = False
                                n_run.font.name = env_font
                                n_run.font.size = Pt(12)
                                curr_p = env_p
                        
                        # --- PERATON TWEAK 3: Disable auto-spacer for Peraton ---
                        if not is_peraton:
                            spacer = curr_p.insert_paragraph_before("")
                            curr_p._p.addnext(spacer._p)
                            try:
                                spacer.style = doc.styles['Normal']
                            except:
                                pass
                            spacer.paragraph_format.space_after = Pt(0)
                            spacer.paragraph_format.space_before = Pt(0)
                    else:
                        is_answer = key in ['A1', 'A2', 'A3', 'A4', 'A5']
                        is_question = key in ['Q1', 'Q2', 'Q3', 'Q4', 'Q5']
                        replace_tag_safely(p, tag, str(value).strip(), unbold=is_answer, force_bold=is_question, font_name=target_font)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    for key, value in mapping.items():
                        tag = f"{{{{{key}}}}}"
                        if tag.lower() in p.text.lower():
                            is_answer = key in ['A1', 'A2', 'A3', 'A4', 'A5']
                            is_question = key in ['Q1', 'Q2', 'Q3', 'Q4', 'Q5']
                            replace_tag_safely(p, tag, str(value) if value else "", unbold=is_answer, force_bold=is_question, font_name=target_font)
    for p in paras_to_remove:
        try:
            delete_paragraph(p)
        except:
            pass

    # Collapse extra blank lines created when optional sections/tables were removed.
    collapse_extra_blank_paragraphs(doc)
    
    doc.save(out_path)
    return out_path


# ====================================================================
# --- 🔴 CLIENT APP 1: FANNIE MAE 🔴 ---
# ====================================================================
def fannie_mae_app():
    TEMPLATE_FILENAME = "Template.docx"
    st.title("Fannie Mae Precision Extractor")

    with st.sidebar:
        st.header("🔑 API Configuration")
        API_KEY = render_ai_api_configuration("fannie")

    st.header("📋 Candidate Information")
    Candidate_Name = st.text_input(
        "Candidate Name (as it should appear on the Fannie submission)",
        key="fm_name",
    )
    col1, col2 = st.columns(2)
    with col1:
        Current_Location_City_ST = st.text_input("Current Location (City, ST)", key="fm_loc")
        Remote_or_Onsite = st.selectbox("Remote or Onsite", ["Remote", "Onsite"], index=1, key="fm_rem")
    with col2:
        Former_FM = st.selectbox("Former FM", ["Y - Per CRC, this candidate is eligible for rehire", "N"], index=1, key="fm_form")
        LinkedIn_GitHub_Portfolio_Link = st.text_input("LinkedIn/GitHub/Portfolio Link", key="fm_link")

    st.header("🎤 Supplier Technical Interview Results")
    # Row 1
    row1_c1, row1_c2 = st.columns(2)
    Question_1 = row1_c1.text_input("Question 1", key="fm_q1")
    Answer_1 = row1_c2.text_area("Answer 1", height=68, key="fm_a1")

    # Row 2
    row2_c1, row2_c2 = st.columns(2)
    Question_2 = row2_c1.text_input("Question 2", key="fm_q2")
    Answer_2 = row2_c2.text_area("Answer 2", height=68, key="fm_a2")

    # Row 3
    row3_c1, row3_c2 = st.columns(2)
    Question_3 = row3_c1.text_input("Question 3", key="fm_q3")
    Answer_3 = row3_c2.text_area("Answer 3", height=68, key="fm_a3")

    # Row 4
    row4_c1, row4_c2 = st.columns(2)
    Question_4 = row4_c1.text_input("Question 4", key="fm_q4")
    Answer_4 = row4_c2.text_area("Answer 4", height=68, key="fm_a4")

    # Row 5
    row5_c1, row5_c2 = st.columns(2)
    Question_5 = row5_c1.text_input("Question 5", key="fm_q5")
    Answer_5 = row5_c2.text_area("Answer 5", height=68, key="fm_a5")

    st.header("📝 Job Description & Notes")

    # --- NEW GOOGLE SHEET LOGIC ---
    # IMPORTANT: Replace this placeholder with your actual Google Sheet link. 
    # The sheet's share settings MUST be set to "Anyone with the link can view".
    SHEET_URL = "https://docs.google.com/spreadsheets/d/1swKaDhGdlmO0ILv7tngkRCbsK-7jF89cdCpf5bypzwM/edit?usp=sharing"

    @st.cache_data(ttl=600)
    def load_reqs(url):
        try:
            # Converts standard Google Sheet URL to a direct CSV download link
            if "/edit" in url:
                csv_url = url.split("/edit")[0] + "/export?format=csv"
            else:
                csv_url = url
            df = pd.read_csv(csv_url)
            return df.fillna("")
        except Exception:
            return pd.DataFrame()

    df_reqs = load_reqs(SHEET_URL)
    options = ["None"]
    req_mapping = {}

    if not df_reqs.empty:
        for idx, row in df_reqs.iterrows():
            req_id = str(row.get("ID", "")).replace(".0", "")
            vms_id = str(row.get("VMS ID", "")).replace(".0", "")
            title = str(row.get("Job Title", ""))
            manager = str(row.get("Manager", "")) # NEW: Extract Manager
            desc = str(row.get("Description", ""))
            notes = str(row.get("FG Notes", ""))
            transcript = str(row.get("Spotlight Transcript", "")) # NEW: Extract Transcript

            # Build the dropdown string safely, ignoring empty values
            option_parts = [req_id, vms_id, title, manager]
            option_str = " - ".join([p.strip() for p in option_parts if p.strip()])
            
            if option_str and option_str != "-":
                options.append(option_str)
                # Added transcript to the mapping dictionary
                req_mapping[option_str] = {"desc": desc, "notes": notes, "transcript": transcript}

    if "fm_jd" not in st.session_state:
        st.session_state.fm_jd = ""
    if "fm_notes" not in st.session_state:
        st.session_state.fm_notes = ""
    if "fm_trans" not in st.session_state:
        st.session_state.fm_trans = ""

    def update_jd_text():
        if "fm_req_selector" not in st.session_state:
            return

        selected = st.session_state.fm_req_selector
        if selected != "None" and selected in req_mapping:
            st.session_state.fm_jd = req_mapping[selected].get("desc", "").strip()
            st.session_state.fm_notes = req_mapping[selected].get("notes", "").strip()
            st.session_state.fm_trans = req_mapping[selected].get("transcript", "").strip()
        else:
            # Clear the text boxes if "None" is selected
            st.session_state.fm_jd = ""
            st.session_state.fm_notes = ""
            st.session_state.fm_trans = ""
            
    selected_req = st.selectbox(
        "🔍 Select a Fannie Mae Requisition (Type to search):",
        options=options,
        key="fm_req_selector",
        on_change=update_jd_text
    )

    Job_Description = st.text_area(
        "1. Official Job Description (Paste generic JD here):", 
        height=150, 
        key="fm_jd"
    )

    Chat_Notes = st.text_area(
        "2. Fieldglass Chat Notes (Optional - Overrides JD):", 
        height=100, 
        key="fm_notes"
    )

    Call_Transcript = st.text_area(
        "3. Spotlight Call Transcript (Optional - Highest Priority):", 
        height=100, 
        key="fm_trans"
    )

    st.header("📂 File Uploads")
    resume_file = st.file_uploader("📤 Upload the candidate's resume...", type=['pdf', 'docx', 'doc'], key="fm_res")

    if st.button("🚀 Generate Fannie Mae Submission", type="primary"):
        if not API_KEY:
            st.error("❌ Error: Please configure the API key for the selected AI provider in the sidebar.")
        elif not Candidate_Name.strip():
            st.error("❌ Error: Please enter the candidate's name exactly as it should appear on the Fannie submission.")
        elif not resume_file:
            st.error("❌ Error: Please upload a resume.")
        elif not os.path.exists(TEMPLATE_FILENAME):
            st.error(f"❌ Error: The preloaded template '{TEMPLATE_FILENAME}' was not found. Please make sure it is uploaded to your GitHub repository.")
        else:
            with st.spinner("Processing document and querying AI..."):
                try:
                    resume_path = f"temp_{resume_file.name}"
                    with open(resume_path, "wb") as f:
                        f.write(resume_file.getbuffer())

                    raw_text = extract_text(resume_path)
                    client = create_ai_client(api_key=API_KEY)

                    prompt = f"""
                    Return a valid JSON object ONLY.

                    RULES:
                    1. Candidate Name: DO NOT infer or extract the candidate name. Fannie uses a recruiter-entered authoritative name field outside this extraction step. Return FullName as an empty string.
                    2. Company Name Cleaning: Display only the primary end-client/employer name that is explicitly supported by the resume. Remove trailing location text. When the resume explicitly labels an End Client/Client separately from a staffing/vendor company, use that stated client name. Do NOT guess or invent an end-client when the source does not identify one.
                    3. Education: Extract School and Degree.
                    4. Experience: Company, Title, Bullets (LIST), Environment (String, optional), Dates.
                        - SOURCE FIDELITY: Bullets are extraction-only historical content. Preserve every substantive source bullet/experience paragraph in ORIGINAL ORDER. One source item must remain one output item. NEVER rewrite, improve grammar, summarize, merge, split, omit, add, or reorder work-history content. Return EVERY professional role shown in the source, including abbreviated or undated roles under Additional Experience, Earlier Experience, Prior Experience, or similar sections. If an abbreviated role has no source dates or bullets, keep Dates blank and Bullets empty rather than omitting the role.
                        - For 'Dates', preserve the date precision from the original resume. If a role lists only years, return only those years (for example, "2018 - 2020"). NEVER invent January, "01", or any other month. If month + year are present, preserve them; mixed-precision ranges must stay mixed.
                        - For 'Title', preserve the actual job title wording. Remove only clearly extraneous employment-type suffixes (for example "- Contract", "(Contract)") or an explicit project/program/client qualifier (for example "Senior Developer - Starship Project" -> "Senior Developer"). Do NOT remove legitimate specialty/technology wording merely because the title contains a dash or parentheses.
                        - For 'Environment', you may ONLY extract this if the original resume explicitly uses the word "Environment:" or "Technologies:" at the bottom of the role. If those exact words are not there, you MUST leave it blank "". Do NOT auto-generate or compile an environment list from the bullet points.
                    5. Certifications: Extract any certifications listed into a single comma-separated string. If none are found, leave it blank "".

                    JSON Structure:
                    {{
                        "FullName": "",
                        "Certifications": "",
                        "Education": [{{"School": "", "Degree": ""}}],
                        "Experience": [{{"Company": "", "Title": "", "Bullets": [], "Environment": "", "Dates": ""}}]
                    }}

                    RESUME: {raw_text}
                    """

                    models_to_try = [
                        'gemini-2.5-flash', 
                        'gemini-3-flash-preview', 
                        'gemini-3.1-flash-lite-preview', 
                        'gemini-pro-latest'
                    ]
                    data = {}
                    
                    for attempt in range(6):
                        if attempt == 0:
                            current_model = models_to_try[0]
                        elif attempt in [1, 2]:
                            current_model = models_to_try[1]
                        elif attempt in [3, 4]:
                            current_model = models_to_try[2]
                        else:
                            current_model = models_to_try[3]
                        
                        try:
                            response = client.models.generate_content(
                                model=current_model,
                                contents=prompt,
                                config=types.GenerateContentConfig(
                                    response_mime_type="application/json"
                                )
                            )
                            data = repair_and_load_json(response.text)
                            break
                        except Exception as e:
                            if "503" in str(e) and attempt < 5:
                                time.sleep(2 ** ((attempt % 2) + 1))
                                continue
                            else:
                                raise e

                    # Fannie v57: the recruiter-entered candidate name is authoritative.
                    # Keep AI name inference completely out of source-fidelity decisions.
                    if isinstance(data, dict):
                        data['FullName'] = ''
                    data = enforce_source_fidelity(data, raw_text, 'Fannie Mae')

                    name = re.sub(r"\s+", " ", Candidate_Name.strip())
                    data['FullName'] = name
                    first_name = _fannie_first_name(name)

                    # v58 Fannie presentation cleanup, source-supported only:
                    # 1) union overlapping/touching date ranges for one shared assignment;
                    # 2) collapse duplicate shared-vendor representations; and
                    # 3) remove broad same-company career umbrella rows when the detailed
                    #    dated subroles are already present, preserving the umbrella summary
                    #    once in the first detailed role.
                    data['Experience'] = _fannie_normalize_compound_assignment_dates(
                        data.get('Experience', [])
                    )
                    data['Experience'] = _fannie_collapse_duplicate_shared_assignments(
                        data.get('Experience', [])
                    )
                    data['Experience'] = _fannie_collapse_umbrella_career_roles(
                        data.get('Experience', [])
                    )

                    mapping = {
                        "FullName": name, "Location": Current_Location_City_ST, "Remote": Remote_or_Onsite,
                        "Certifications": data.get("Certifications", ""),
                        "FormerFM": Former_FM, "Links": LinkedIn_GitHub_Portfolio_Link,
                        "Q1": Question_1, "A1": Answer_1, "Q2": Question_2, "A2": Answer_2,
                        "Q3": Question_3, "A3": Answer_3, "Q4": Question_4, "A4": Answer_4, "Q5": Question_5, "A5": Answer_5,
                        "SUMMARY": "", "SKILL1": "", "YEARS1": "", "SKILL2": "", "YEARS2": "",
                        "SKILL3": "", "YEARS3": "", "SKILL4": "", "YEARS4": ""
                    }

                    edu = data.get('Education', [])
                    for i in range(1, 4):
                        mapping[f"School{i}"] = clean_school(edu[i-1].get('School', '')) if i <= len(edu) else ""
                        mapping[f"Degree{i}"] = edu[i-1].get('Degree', '') if i <= len(edu) else ""

                    exp = data.get('Experience', [])
                    for i in range(1, max(7, len(exp)) + 1):
                        if i <= len(exp):
                            mapping[f"Company{i}"] = clean_company_name(exp[i-1].get('Company', ''))
                            mapping[f"Title{i}"] = clean_job_title(exp[i-1].get('Title', ''))
                            mapping[f"Bullets{i}"] = clean_bullets(exp[i-1].get('Bullets', []))
                            mapping[f"Environment{i}"] = exp[i-1].get('Environment', '')
                            mapping[f"Dates{i}"] = standardize_dates(exp[i-1].get('Dates', ''))
                        else:
                            mapping[f"Company{i}"] = ""
                            mapping[f"Title{i}"] = ""
                            mapping[f"Bullets{i}"] = ""
                            mapping[f"Environment{i}"] = ""
                            mapping[f"Dates{i}"] = ""

                    if Job_Description.strip():
                        try:
                            summary_prompt = f"""
                            Return a valid JSON object ONLY.

                            You are an elite Senior Technical Recruiter preparing a Fannie Mae
                            Fieldglass candidate submission. Restore the proven Fannie narrative
                            style used by successful submissions: four connected recruiter-quality
                            sentences that build a business case, plus four concise high-signal
                            Skill & Competency rows.

                            ========================
                            SOURCE / PRIORITY MODEL
                            ========================
                            CANDIDATE FACTS:
                            - ORIGINAL RESUME is the primary factual source of candidate experience.
                            - Supplier Technical Interview Q&A is secondary and may clarify depth or
                              reinforce experience already supported by the resume. It must not create
                              unsupported candidate experience.

                            HIRING-TEAM EMPHASIS:
                            1. SPOTLIGHT CALL TRANSCRIPT = highest-priority manager emphasis.
                            2. FIELDGLASS CHAT NOTES = next-highest manager/MSP emphasis.
                            3. OFFICIAL JOB DESCRIPTION = broad requirements and ATS terminology.

                            ATS / TERMINOLOGY COVERAGE:
                            - The Official Job Description remains the primary source for broad
                              Fieldglass keyword/phrase coverage.
                            - Spotlight/Chat Notes should change emphasis and prioritization without
                              needlessly erasing important JD concepts unless they contradict them.
                            - Preserve exact JD terminology when it is useful AND genuinely supported
                              by the candidate's resume/Q&A.
                            - Never turn manager/JD language into candidate history.

                            ========================
                            THE FANNIE NARRATIVE BLUEPRINT - EXACTLY 4 SENTENCES
                            ========================
                            Return SUMMARY1, SUMMARY2, SUMMARY3, and SUMMARY4 as four separate,
                            complete sentences. Together they must read as ONE polished recruiter
                            narrative. Every sentence must strengthen the business case for the
                            candidate rather than merely restating resume facts.

                            SUMMARY1 - THE ANCHOR / AUTHORITY
                            - MUST begin naturally with "{first_name} is".
                            - Identify the candidate's honest target-relevant professional identity,
                              supported experience/domain depth, and the PRIMARY must-have they solve.
                            - If the target JD title accurately reflects the candidate's demonstrated
                              history, you may use it. Otherwise use the strongest truthful professional
                              identity supported by the resume.
                            - Total-years language must be source-supported and defensible. Do not
                              invent precision or use the phrase "progressive experience".

                            SUMMARY2 - THE ALIGNMENT / HOOK
                            - Name the current/most-recent employer when it provides useful relevant
                              evidence. If an earlier employer/role is substantially stronger evidence
                              for the target need, use that stronger role instead.
                            - Highlight the single strongest accomplishment/responsibility showing the
                              candidate has actually performed the core work this Fannie role requires.
                            - Show the connection through evidence, not generic "fit" language.

                            SUMMARY3 - THE EXECUTION & IMPACT / PROOF
                            - Explain HOW the candidate executed the relevant work AND WHY IT MATTERED.
                            - Include tools/methodologies naturally when useful, but do not write a
                              comma-separated inventory.
                            - Emphasize scale, complexity, operational ownership, implementation,
                              testing/support, regulatory/business significance, measurable impact, or
                              another source-supported proof point.
                            - Do not simply list activities. This sentence must add meaning.

                            SUMMARY4 - THE EVIDENCE-TO-ROLE BRIDGE
                            - Synthesize the strongest proven signals into a concise statement of
                              transferable, directly relevant experience.
                            - Optimize for BOTH Fannie audiences:
                              * Fieldglass/MSP: make the candidate-to-job match unmistakable, including
                                high-value JD terminology when it is genuinely candidate-supported.
                              * Hiring Manager: describe what the candidate has already demonstrated
                                and how that experience transfers naturally to the work, without
                                explaining the manager's own requirements back to them.
                            - This must function as a true closing argument, not introduce one more
                              disconnected resume fact.
                            - Prefer evidence language such as:
                              "{first_name}'s combination of [X], [Y], and [Z] provides directly
                              relevant experience supporting [target capability] from [stage] through [stage]."
                              or
                              "{first_name}'s experience taking [supported initiative/work] from [stage]
                              through [stage] provides relevant experience for [target work/capability]."
                              Adapt naturally; do not copy these mechanically.
                            - Do NOT use judgment-based closers such as "perfect fit", "ideal candidate",
                              "strong fit", "well positioned", or "aligns with the role's needs/requirements".
                            - Do NOT state "this role needs/requires..." or otherwise explain the hiring
                              manager's own job back to them.
                            - Do NOT promise future performance or use "Day 1", "immediate asset", or
                              "immediate value".

                            ========================
                            SUMMARY STYLE & FINAL POLISH - STRICT
                            ========================
                            - Write like a human recruiter pitching to a knowledgeable colleague:
                              confident, direct, specific, and factual.
                            - SHOW, DON'T TELL. Prefer evidence of ownership/execution over adjectives.
                            - Prefer clear business language over consultant buzzwords.
                            - Use verbs that naturally fit the work. Do not force dramatic leadership verbs.
                            - Do not use generic filler such as "strong background", "highly experienced",
                              "proven track record", "results-driven", "seasoned", "positions them uniquely",
                              "fits well", "well positioned", or canned role-judgment phrases such
                              as "aligns with the role's needs/requirements". Natural use of "align" in
                              other factual contexts is not prohibited.
                            - Do not use transition crutches such as "Additionally", "Furthermore", or "Moreover".
                            - Do not mention location, rate, availability, work authorization, or submission logistics.
                            - Do not use em dashes. Use commas, colons, semicolons, parentheses, or standard hyphens.
                            - Avoid repeating the same verb/concept across sentences when a cleaner alternative exists.
                            - Keep tool density readable. Do not turn any sentence into a keyword dump.
                            - Prefer resume-demonstrated accomplishments and recurring ownership over skills-list mentions.
                            - Unless the role is explicitly implementation-focused, favor evidence of actual
                              day-to-day execution, issue resolution, testing, support, governance, compliance,
                              platform/process ownership, or measurable business outcomes over vague participation.

                            EXAMPLE OF THE NARRATIVE QUALITY / FLOW TO EMULATE:
                            "Sarah is a Senior Data Engineer with 7+ years of experience architecting cloud-native data migrations in regulated financial environments. Most recently at Capital One, she led an end-to-end legacy data warehouse migration to AWS, providing direct evidence of large-scale cloud delivery and governance. By engineering automated ETL pipelines with Python, PySpark, and Apache Airflow, she processed 5TB of daily transaction data and reduced reporting latency by 40%. Sarah's combination of AWS migration, automated data engineering, and regulated-data governance gives her directly relevant experience carrying cloud data modernization from architecture through production delivery."
                            Do not copy facts or wording from this example. Copy only the structure and quality.

                            ========================
                            FANNIE SKILLS TABLE - PRESERVE v57 ARCHITECTURE
                            ========================
                            - EXACTLY 4 high-signal rows when four defensible rows exist.
                            - Treat the four rows as scarce Fieldglass screening space.
                            - Prioritize the specific must-have technologies AND methodologies requested
                              in the JD, with Spotlight/Chat priorities taking precedence when provided.
                            - Keep rows highly relevant and keyword-rich, but use only candidate-supported evidence.
                            - Choose four materially different screening dimensions. Consolidate closely
                              related concepts rather than wasting rows on redundant categories.
                            - Avoid repeating the same parenthetical detail/tool across rows unless genuinely unavoidable.
                            - Use up to 6 supporting details, but use fewer when that makes the row cleaner.
                            - Prefer demonstrated work-history evidence over standalone skill-list mentions.
                            - Preserve exact JD terminology where supported by the candidate.
                            - If fewer than four defensible relevant competencies exist, leave unused fields
                              blank rather than fabricating filler.

                            FORMAT:
                                "Competency Area (Supporting Detail, Supporting Detail, Tool)"

                            DISPLAY / CAPITALIZATION:
                            - Use professional standard capitalization exactly like successful Fannie submissions:
                              "Data Engineering (Python, SQL, ETL/ELT, Data Validation)"
                              "Generative AI & LLM Integration (Prompt Engineering, LLM APIs, FastAPI, Pydantic)"
                            - Generic competency/detail phrases use professional Title Case.
                            - Preserve canonical tool/platform/acronym casing such as JIRA, Power BI,
                              FastAPI, PySpark, ETL/ELT, AWS, SQL, Summit, and Microsoft 365.

                            YEARS OF EXPERIENCE + YEAR LAST USED:
                            - Give the best defensible tenure for THAT competency. Do not bias it high or low.
                            - A long value such as 14+ years is correct when the resume supports it.
                            - Do not substitute total-career years unless the competency truly spans that period.
                            - Do not arbitrarily subtract years from specialized skills.
                            - Use dated work history and explicit source-supported tenure statements.
                            - "current" means the competency is demonstrated in the current ongoing role.
                              Otherwise use the most recent supported four-digit year.
                            - Valid formats only: "X+ years, current", "X+ years, YYYY",
                              "<1 year, current", or "<1 year, YYYY".
                            - NEVER return a dangling value such as "14+ years,".

                            ZERO-TOLERANCE FACT RULES:
                            - Never copy JD-only tools/skills into candidate experience.
                            - Never infer a specific tool from a broader platform.
                            - Never inflate ownership, proficiency, tenure, recency, metrics, or scope.
                            - Before returning JSON, verify every candidate claim and every skill detail
                              against the resume/Q&A.

                            OUTPUT FORMAT:
                            {{
                              "SUMMARY1": "Anchor sentence",
                              "SUMMARY2": "Alignment / hook sentence",
                              "SUMMARY3": "Execution + impact / proof sentence",
                              "SUMMARY4": "Evidence-based closer sentence",
                              "SKILL1": "Competency Area (Supporting Detail, Tool)",
                              "YEARS1": "X+ years, current",
                              "SKILL2": "Competency Area (Supporting Detail, Tool)",
                              "YEARS2": "X+ years, YYYY",
                              "SKILL3": "Competency Area (Supporting Detail, Tool)",
                              "YEARS3": "X+ years, current",
                              "SKILL4": "Competency Area (Supporting Detail, Tool)",
                              "YEARS4": "X+ years, YYYY"
                            }}

                            CANDIDATE FULL NAME (authoritative recruiter input):
                            {name}

                            CANDIDATE FIRST NAME:
                            {first_name}

                            OFFICIAL JOB DESCRIPTION:
                            {Job_Description}

                            FIELDGLASS CHAT NOTES:
                            {Chat_Notes}

                            SPOTLIGHT CALL TRANSCRIPT:
                            {Call_Transcript}

                            TECHNICAL INTERVIEW Q&A:
                            Q1: {Question_1}
                            A1: {Answer_1}
                            Q2: {Question_2}
                            A2: {Answer_2}
                            Q3: {Question_3}
                            A3: {Answer_3}
                            Q4: {Question_4}
                            A4: {Answer_4}
                            Q5: {Question_5}
                            A5: {Answer_5}

                            ORIGINAL RESUME:
                            {raw_text}
                            """
                            time.sleep(2)
                            summary_data = {}

                            for attempt in range(6):
                                if attempt == 0:
                                    current_model = models_to_try[0]
                                elif attempt in [1, 2]:
                                    current_model = models_to_try[1]
                                elif attempt in [3, 4]:
                                    current_model = models_to_try[2]
                                else:
                                    current_model = models_to_try[3]

                                try:
                                    summary_response = client.models.generate_content(
                                        model=current_model,
                                        contents=summary_prompt,
                                        config=types.GenerateContentConfig(response_mime_type="application/json"),
                                    )
                                    summary_data = repair_and_load_json(summary_response.text)
                                    # Backward-compatible normalization: if the model ever
                                    # returns the legacy single SUMMARY field, split it once
                                    # into the four v59 sentence slots before QA/mapping.
                                    if isinstance(summary_data, dict) and not any(
                                        str(summary_data.get(f"SUMMARY{i}", "") or "").strip()
                                        for i in range(1, 5)
                                    ):
                                        legacy_sentences = _fannie_summary_sentence_values(summary_data)
                                        for idx, sentence in enumerate(legacy_sentences, 1):
                                            if sentence:
                                                summary_data[f"SUMMARY{idx}"] = sentence
                                    break
                                except Exception as api_e:
                                    if "503" in str(api_e) and attempt < 5:
                                        time.sleep(2 ** ((attempt % 2) + 1))
                                        continue
                                    raise

                            # ----------------------------------------------------
                            # v59 SUMMARY-ONLY QA / REPAIR
                            # ----------------------------------------------------
                            # Keep the restored narrative architecture isolated from
                            # skills so a weak summary cannot cause Luna to rewrite an
                            # already-good skills table.
                            summary_issues = _fannie_summary_validation_issues(
                                summary_data,
                                first_name,
                            )
                            if summary_issues:
                                summary_repair_prompt = f"""
                                Return a valid JSON object ONLY with SUMMARY1-SUMMARY4.

                                Repair ONLY the four Fannie Mae summary sentences. Preserve candidate
                                facts and do not change/add experience, tools, employers, metrics, dates,
                                tenure, or responsibilities that are not supported by the source.

                                CANDIDATE FULL NAME: {name}
                                CANDIDATE FIRST NAME: {first_name}

                                QUALITY ISSUES TO REPAIR:
                                {chr(10).join('- ' + issue for issue in summary_issues)}

                                REQUIRED BLUEPRINT:
                                - SUMMARY1: Anchor/Authority. Begin naturally with "{first_name} is" and
                                  establish target-relevant identity + supported experience + primary must-have.
                                - SUMMARY2: Alignment/Hook. Use the strongest employer/role evidence for the
                                  central requirement. Current employer is preferred when genuinely relevant;
                                  earlier experience may be used when materially stronger.
                                - SUMMARY3: Execution & Impact/Proof. Explain HOW the work was executed AND
                                  WHY IT MATTERED through source-supported scale, complexity, ownership,
                                  implementation, support/testing, regulatory significance, or impact.
                                - SUMMARY4: Evidence-to-Role Bridge. Synthesize the strongest proven
                                  signals into transferable, directly relevant experience. Make the match
                                  obvious to Fieldglass/MSP review while remaining useful to the hiring
                                  manager. Do not introduce another disconnected resume fact, declare the
                                  candidate a fit, or explain the role's own needs/requirements back to the reader.
                                  Prefer a natural bridge such as "[Name]'s combination of X, Y, and Z
                                  provides directly relevant experience supporting [target capability] from A
                                  through B," adapted only to facts supported by the source.

                                STYLE:
                                - Four complete, connected recruiter-quality sentences.
                                - Human, direct, specific, evidence-first.
                                - No Day 1, immediate asset/value, progressive experience, proven track record,
                                  results-driven, seasoned, highly experienced, strong background, perfect fit,
                                  excellent/ideal/strong fit, well positioned, "aligns with the role's
                                  needs/requirements," or future-performance promises.
                                - No em dashes.
                                - Do not mention location, rate, availability, or work authorization.
                                - Preserve exact useful JD terminology only when candidate-supported.

                                HIRING PRIORITY: Spotlight > Fieldglass Chat Notes > Official JD.
                                ATS TERMINOLOGY: Official JD remains the broad keyword/phrase source.

                                OFFICIAL JOB DESCRIPTION:
                                {Job_Description}

                                FIELDGLASS CHAT NOTES:
                                {Chat_Notes}

                                SPOTLIGHT CALL TRANSCRIPT:
                                {Call_Transcript}

                                ORIGINAL RESUME:
                                {raw_text}

                                CURRENT SUMMARY DRAFT:
                                {json.dumps({k: summary_data.get(k, '') for k in ('SUMMARY1','SUMMARY2','SUMMARY3','SUMMARY4')}, ensure_ascii=False, indent=2)}

                                OUTPUT:
                                {{
                                  "SUMMARY1": "",
                                  "SUMMARY2": "",
                                  "SUMMARY3": "",
                                  "SUMMARY4": ""
                                }}
                                """
                                try:
                                    repair_response = client.models.generate_content(
                                        model=models_to_try[0],
                                        contents=summary_repair_prompt,
                                        config=types.GenerateContentConfig(response_mime_type="application/json"),
                                    )
                                    repaired = repair_and_load_json(repair_response.text)
                                    if isinstance(repaired, dict):
                                        for key in ("SUMMARY1", "SUMMARY2", "SUMMARY3", "SUMMARY4"):
                                            if str(repaired.get(key, "") or "").strip():
                                                summary_data[key] = repaired[key]
                                except Exception:
                                    pass

                            # ----------------------------------------------------
                            # v59 SKILLS-ONLY QA / REPAIR
                            # ----------------------------------------------------
                            # Preserve the v57 skills architecture. Only repair the
                            # skills payload when its own narrow checks fail.
                            skill_issues = _fannie_skills_validation_issues(
                                summary_data,
                                raw_text,
                            )
                            if skill_issues:
                                skill_repair_prompt = f"""
                                Return a valid JSON object ONLY with SKILL1-4 and YEARS1-4.

                                Repair ONLY the Fannie Skill & Competency rows. Do not alter the summary.
                                Keep the proven v57 Fannie presentation style.

                                REQUIRED REPAIRS:
                                {chr(10).join('- ' + issue for issue in skill_issues)}

                                RULES:
                                - Four distinct, high-value JD/manager-relevant rows when supported.
                                - Format: "Competency Area (Supporting Detail, Tool)".
                                - Professional Title Case for generic phrases; preserve canonical tool/acronym casing.
                                - Avoid repeated parenthetical details across rows unless unavoidable.
                                - Use only candidate-supported skills/details.
                                - Preserve exact JD terminology when genuinely supported.
                                - Give the best defensible skill-specific tenure without upward/downward bias.
                                - Every YEARS value ends in "current" or a four-digit last-used year.
                                - Do not invent JD-only experience and do not use em dashes.

                                HIRING PRIORITY: Spotlight > Fieldglass Chat Notes > Official JD.
                                ATS TERMINOLOGY: Official JD remains the broad keyword/phrase source.

                                OFFICIAL JOB DESCRIPTION:
                                {Job_Description}

                                FIELDGLASS CHAT NOTES:
                                {Chat_Notes}

                                SPOTLIGHT CALL TRANSCRIPT:
                                {Call_Transcript}

                                ORIGINAL RESUME:
                                {raw_text}

                                CURRENT SKILLS DRAFT:
                                {json.dumps({k: summary_data.get(k, '') for k in ('SKILL1','YEARS1','SKILL2','YEARS2','SKILL3','YEARS3','SKILL4','YEARS4')}, ensure_ascii=False, indent=2)}

                                OUTPUT:
                                {{
                                  "SKILL1": "", "YEARS1": "",
                                  "SKILL2": "", "YEARS2": "",
                                  "SKILL3": "", "YEARS3": "",
                                  "SKILL4": "", "YEARS4": ""
                                }}
                                """
                                try:
                                    repair_response = client.models.generate_content(
                                        model=models_to_try[0],
                                        contents=skill_repair_prompt,
                                        config=types.GenerateContentConfig(response_mime_type="application/json"),
                                    )
                                    repaired = repair_and_load_json(repair_response.text)
                                    if isinstance(repaired, dict):
                                        for key in ("SKILL1","YEARS1","SKILL2","YEARS2","SKILL3","YEARS3","SKILL4","YEARS4"):
                                            if key in repaired:
                                                summary_data[key] = repaired[key]
                                except Exception:
                                    pass

                            remaining_summary_issues = _fannie_summary_validation_issues(
                                summary_data,
                                first_name,
                            )
                            remaining_skill_issues = _fannie_skills_validation_issues(
                                summary_data,
                                raw_text,
                            )
                            remaining_fannie_issues = remaining_summary_issues + remaining_skill_issues
                            # v59: successful self-repair is intentionally quiet. Only notify
                            # when generated-content QA still has unresolved issues after the
                            # summary-only / skills-only repair passes have already run.
                            if remaining_fannie_issues:
                                notify_formatter_diagnostic(
                                    "Fannie Mae",
                                    "WARNING",
                                    "Fannie generated summary/skills QA still had unresolved issues after nonblocking repair.",
                                    raw_text=raw_text,
                                    uploaded_filename=resume_file.name,
                                    technical_details="\n".join(remaining_fannie_issues[:25]),
                                )

                            summary_sentences = [
                                _fannie_finalize_summary_sentence(summary_data.get(f"SUMMARY{i}", ""))
                                for i in range(1, 5)
                            ]
                            summary_sentences = [x for x in summary_sentences if x]
                            mapping["SUMMARY"] = " ".join(summary_sentences)
                            mapping["SKILL1"] = _fannie_polish_skill_display(summary_data.get("SKILL1", ""))
                            mapping["YEARS1"] = _fannie_safe_years_display(summary_data.get("YEARS1", ""))
                            mapping["SKILL2"] = _fannie_polish_skill_display(summary_data.get("SKILL2", ""))
                            mapping["YEARS2"] = _fannie_safe_years_display(summary_data.get("YEARS2", ""))
                            mapping["SKILL3"] = _fannie_polish_skill_display(summary_data.get("SKILL3", ""))
                            mapping["YEARS3"] = _fannie_safe_years_display(summary_data.get("YEARS3", ""))
                            mapping["SKILL4"] = _fannie_polish_skill_display(summary_data.get("SKILL4", ""))
                            mapping["YEARS4"] = _fannie_safe_years_display(summary_data.get("YEARS4", ""))
                        except Exception as e:
                            st.warning(f"⚠️ Warning: Summary generation failed. Proceeding without it. ({e})")

                    safe_name_for_file = re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("_") or "Candidate"
                    out_file = f"Submission_Fannie_{safe_name_for_file}.docx"
                    process_word_doc(TEMPLATE_FILENAME, mapping, out_file)
                    
                    with open(out_file, "rb") as file:
                        btn = st.download_button(
                            label="⬇️ Download Generated Document",
                            data=file,
                            file_name=out_file,
                            mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                            type="primary"
                        )
                    
                    st.success(f"✅ Success! Document is ready for download.")

                    try:
                        os.remove(resume_path)
                    except:
                        pass

                except Exception as e:
                    notify_formatter_diagnostic(
                        "Fannie Mae", "FATAL", str(e),
                        uploaded_filename=getattr(locals().get("resume_file"), "name", ""),
                    )
                    st.error(f"❌ Process Failed: {str(e)}")


